   /// R3064000: what a Dormant card's awakening gives its controller, keyed as `ActivationPrice` is.
   pub type AwakenPrice = ActivationPrice;

   /// R3064000: whether the face `card` runs has a trigger answering `awakened` (`script_of`: Vanilla has none).
   fn has_wake_trigger(state: &GameState, card: &CardInstance) -> bool {
       script_of(state, card).triggers.iter().any(|trigger| trigger.on.contains(&GameEventType::Awakened))
   }

   /// R3064000: what `unit`'s awakening gives its controller, by `prices`, while its face has a wake
   /// trigger. 0 with `Prices::NONE`, for an unpriced card and at a zero `awaken` weight.
   fn awaken_price(state: &GameState, unit: &CardInstance, w: &EvalWeights, prices: &Prices) -> f64 {
       if w.awaken == 0.0 {
           return 0.0;
       }
       let price = prices.awakenings.iter().find(|entry| entry.is_for(unit)).map(|entry| entry.price);
       match price {
           Some(price) if has_wake_trigger(state, unit) => price,
           _ => 0.0,
       }
   }
   ```

