   ```rust
   fn woken(before: &GameState, id: &str) -> GameState {
       settled_after(before, |sink| { awaken_card(sink, id); })
   }

   /// One node; `None` when refused, `Some(None)` on a panic (`note_sim_panic`), an open prompt or a finished game.
   fn wake_once(before: &GameState, id: &str, counter: &dyn NodeCounter) -> Option<Option<GameState>> {
       if !counter.take() { return None; }
       match catch_unwind(AssertUnwindSafe(|| woken(before, id))) {
           Ok(after) => Some((after.pending.is_none() && after.result.is_none()).then_some(after)),
           Err(payload) => { note_sim_panic(counter, payload.as_ref()); Some(None) }
       }
   }

   /// The controller's evaluation after `unit` wakes less after its hookless twin wakes (text given back
   /// before scoring), plus `AI_EVAL.next_turn_mana` per crystal gained over the twin. Signed. Two nodes.
   fn awaken_probe(before: &GameState, unit: &CardInstance, counter: &dyn NodeCounter) -> Option<Option<f64>> {
       let owner = unit.controller;
       let Some(hooked) = wake_once(before, &unit.id, counter)? else { return Some(None); };
       let (twin, printed) = hookless_twin(before, unit);
       let Some(plain) = wake_once(&twin, &unit.id, counter)? else { return Some(None); };
       let plain = with_text_back(plain, &unit.id, &printed);
       let gained = hooked.players[owner].mana.current - plain.players[owner].mana.current;
       Some(Some(
           evaluate(&hooked, owner, NextSwing::Enemy, &AI_EVAL)
               - evaluate(&plain, owner, NextSwing::Enemy, &AI_EVAL)
               + AI_EVAL.next_turn_mana * f64::from(gained),
       ))
   }

   /// `awaken_probe` for a Unit in `seat`'s hand, placed first (`spawn_hand_unit`); it must enter Dormant.
   fn spawned_awaken_probe(world: &GameState, seat: PlayerId, card: &CardInstance, counter: &dyn NodeCounter)
       -> Option<Option<f64>> {
       let Some((placed, unit)) = spawn_hand_unit(world, seat, card, counter)? else { return Some(None); };
       if !is_slumbering(&unit) { return Some(None); }
       awaken_probe(&placed, &unit, counter)
   }

   pub fn awaken_prices(world: &GameState, seat: PlayerId, counter: &dyn NodeCounter) -> Vec<AwakenPrice> {
       if AI_EVAL.awaken == 0.0 || world.pending.is_some() || world.result.is_some() {
           return Vec::new();
       }
       let field = [seat, seat.opponent()].into_iter()
           .flat_map(|player| units_on_field_of(world, player))
           .filter(|unit| is_slumbering(unit) && has_wake_trigger(world, unit))
           .map(|unit| (unit, false));
       let hand = world.players[seat].hand.iter()
           .filter(|card| card_type_of_face(world, &card.def_id, card.radiant) == CardType::Unit
               && has_wake_trigger(world, card))
           .map(|card| (card, true));
       let mut candidates: Vec<(AwakenPrice, &CardInstance, bool)> = Vec::new();
       for (card, in_hand) in field.chain(hand) {
           if !candidates.iter().any(|(key, _, _)| key.is_for(card)) {
               candidates.push((AwakenPrice::key(card), card, in_hand));
           }
       }
       if candidates.is_empty() { return Vec::new(); }   // no node spent
       let mut sandbox = world.clone();
       sandbox.sandbox = Some(true);
       for player in PLAYER_IDS { sandbox.players[player].auto_end_turn = Some(false); }
       let probes = create_sub_counter(counter, AI_AWAKEN_PROBE_NODES);
       let mut priced = Vec::new();
       for (key, card, in_hand) in candidates {
           let probed = if in_hand { spawned_awaken_probe(&sandbox, seat, card, &probes) }
                        else { awaken_probe(&sandbox, card, &probes) };
           match probed {
               None => break,
               Some(None) => {}
               Some(Some(price)) => priced.push(AwakenPrice { price, ..key }),
           }
       }
       priced
   }
   ```
